import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"VPS Control Panel User Guide","description":"","frontmatter":{"title":"VPS Control Panel User Guide"},"headers":[],"relativePath":"operations-knowledge-base/vps/vps-control-panel-user-guide.md","filePath":"operations-knowledge-base/vps/vps-control-panel-user-guide.md","lastUpdated":1794309341000}'),s={name:"operations-knowledge-base/vps/vps-control-panel-user-guide.md"};function i(n,e,l,p,d,h){return t(),a("div",null,[...e[0]||(e[0]=[r('<h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>This document introduces the main functions and basic operations available in the VPS control panel, helping customers quickly become familiar with managing their VPS through the Raksmart Client Portal.</p><p>For features such as Upgrade/Downgrade, Elastic IP, Cloud Disk, Security Groups, and Snapshots, this document provides only a brief overview. For detailed instructions, please refer to the corresponding knowledge base articles.</p><p><strong>Supported Product:</strong></p><ul><li>VPS (Virtual Private Server)</li></ul><hr><h2 id="_1-accessing-the-vps-control-panel" tabindex="-1">1. Accessing the VPS Control Panel <a class="header-anchor" href="#_1-accessing-the-vps-control-panel" aria-label="Permalink to &quot;1. Accessing the VPS Control Panel&quot;">​</a></h2><h3 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h3><ol><li>Log in to the <strong>Raksmart Client Portal</strong>.</li><li>Go to <strong>Product Management → VPS</strong>.</li><li>Select the VPS you want to manage.</li><li>Open the VPS details page.</li></ol><p>The page displays basic server information, including:</p><ul><li>Region</li><li>CPU</li><li>Memory</li><li>Operating System</li><li>IP Address</li><li>Login Password (copy supported)</li><li>VNC</li><li>Upgrade/Downgrade</li></ul><hr><h2 id="_2-server-information" tabindex="-1">2. Server Information <a class="header-anchor" href="#_2-server-information" aria-label="Permalink to &quot;2. Server Information&quot;">​</a></h2><p>The left panel displays the basic information of your VPS, including:</p><ul><li>Region</li><li>CPU</li><li>Memory</li><li>System Disk Specifications</li><li>Username</li><li>SSH Port (Linux)</li><li>Notes (if configured)</li></ul><p>Customers can quickly view the current server configuration and login information from this page.</p><hr><h2 id="_3-power-management" tabindex="-1">3. Power Management <a class="header-anchor" href="#_3-power-management" aria-label="Permalink to &quot;3. Power Management&quot;">​</a></h2><p>The left panel provides the most commonly used power management functions.</p><p>Available options include:</p><ul><li>Power On</li><li>Shut Down</li><li>Reboot</li><li>Force Shut Down</li><li>Force Reboot</li><li>Reset Password</li><li>Reinstall OS</li><li>Rescue System</li></ul><p>The functions are described below.</p><hr><h2 id="power-on" tabindex="-1">Power On <a class="header-anchor" href="#power-on" aria-label="Permalink to &quot;Power On&quot;">​</a></h2><p>Starts a VPS that is currently powered off.</p><p>Typical use cases:</p><ul><li>The VPS has been shut down.</li><li>Restarting services after maintenance.</li></ul><hr><h2 id="shut-down" tabindex="-1">Shut Down <a class="header-anchor" href="#shut-down" aria-label="Permalink to &quot;Shut Down&quot;">​</a></h2><p>Performs a graceful shutdown of the operating system.</p><p>It is recommended to use this option before maintenance or when stopping services.</p><hr><h2 id="reboot" tabindex="-1">Reboot <a class="header-anchor" href="#reboot" aria-label="Permalink to &quot;Reboot&quot;">​</a></h2><p>Performs a normal reboot of the VPS.</p><p>Typical use cases:</p><ul><li>Applying system updates.</li><li>Activating configuration changes.</li><li>Restarting the system after troubleshooting.</li></ul><hr><h2 id="force-shut-down" tabindex="-1">Force Shut Down <a class="header-anchor" href="#force-shut-down" aria-label="Permalink to &quot;Force Shut Down&quot;">​</a></h2><p>Immediately powers off the VPS.</p><p><strong>Note:</strong></p><p>A force shutdown does not allow the operating system to shut down gracefully and may result in data loss or file system corruption. It should only be used when a normal shutdown is not possible.</p><hr><h2 id="force-reboot" tabindex="-1">Force Reboot <a class="header-anchor" href="#force-reboot" aria-label="Permalink to &quot;Force Reboot&quot;">​</a></h2><p>Immediately restarts the VPS.</p><p><strong>Note:</strong></p><p>This option should only be used when the server is unresponsive and a normal reboot cannot be performed.</p><hr><h2 id="reset-password" tabindex="-1">Reset Password <a class="header-anchor" href="#reset-password" aria-label="Permalink to &quot;Reset Password&quot;">​</a></h2><p>Resets the system login password.</p><p>Typical use cases:</p><ul><li>Forgotten login password.</li><li>Changing the default password after deployment.</li></ul><p>For detailed instructions, please refer to:</p><p><strong><a href="/operations-knowledge-base/baremetal/bare-metal-cloud-password-change-and-reset-guide.html">Bare Metal Cloud Password Change &amp; Reset Guide</a></strong></p><hr><h2 id="reinstall-os" tabindex="-1">Reinstall OS <a class="header-anchor" href="#reinstall-os" aria-label="Permalink to &quot;Reinstall OS&quot;">​</a></h2><p>Reinstalls the operating system of the VPS.</p><p>Linux and Windows operating systems are supported, depending on the available options shown in the control panel.</p><p><strong>Note:</strong></p><p>Reinstalling the operating system will erase all data on the system disk. Please back up important data before proceeding.</p><p>For detailed instructions, please refer to:</p><p><strong><a href="/operations-knowledge-base/baremetal/bare-metal-cloud-os-reinstallation-guide.html">Bare Metal Cloud OS Reinstallation Guide</a></strong></p><hr><h2 id="rescue-system" tabindex="-1">Rescue System <a class="header-anchor" href="#rescue-system" aria-label="Permalink to &quot;Rescue System&quot;">​</a></h2><p>When the operating system cannot boot normally, you can enter Rescue Mode to repair the system or recover data.</p><p>Typical use cases:</p><ul><li>Operating system fails to boot.</li><li>File system repair.</li><li>Boot configuration recovery.</li><li>Data recovery.</li></ul><p>For detailed instructions, please refer to:</p><p><strong><a href="/operations-knowledge-base/baremetal/bare-metal-cloud-rescue-mode-user-guide.html">Bare Metal Cloud Rescue System Guide</a></strong></p><hr><h2 id="_4-vnc-console" tabindex="-1">4. VNC Console <a class="header-anchor" href="#_4-vnc-console" aria-label="Permalink to &quot;4. VNC Console&quot;">​</a></h2><p>Click the <strong>VNC</strong> button at the top of the page to open the server console.</p><p>The VNC console allows you to access the server even if network connectivity is unavailable.</p><p>Typical use cases:</p><ul><li>SSH connection failure.</li><li>Remote Desktop (RDP) connection failure.</li><li>Password recovery.</li><li>Viewing the boot process.</li><li>System maintenance.</li></ul><p>For detailed instructions, please refer to:</p><p><strong><a href="/operations-knowledge-base/baremetal/bare-metal-cloud-vnc-console-user-guide.html">Bare Metal Cloud VNC Console Guide</a></strong></p><hr><h2 id="_5-upgrade-downgrade" tabindex="-1">5. Upgrade/Downgrade <a class="header-anchor" href="#_5-upgrade-downgrade" aria-label="Permalink to &quot;5. Upgrade/Downgrade&quot;">​</a></h2><p>Click the <strong>Upgrade/Downgrade</strong> button at the top of the page to adjust your VPS resources according to your business requirements.</p><p>Available upgrade or downgrade options may include:</p><ul><li>CPU</li><li>Memory</li><li>Bandwidth</li><li>Traffic</li></ul><p>The available resources depend on the options displayed in the control panel.</p><p>For detailed instructions, please refer to:</p><p><strong><a href="/operations-knowledge-base/baremetal/bare-metal-cloud-upgrade-downgrade-guide.html">Bare Metal Cloud Upgrade/Downgrade Guide</a></strong></p><hr><h2 id="_6-charts" tabindex="-1">6. Charts <a class="header-anchor" href="#_6-charts" aria-label="Permalink to &quot;6. Charts&quot;">​</a></h2><p>The <strong>Charts</strong> page displays real-time monitoring information for your VPS.</p><p>Available monitoring metrics include:</p><ul><li>CPU Usage</li><li>Disk I/O</li><li>Memory Usage</li><li>Network Traffic</li></ul><p>These charts help you monitor the operating status and resource utilization of your VPS.</p><p>For more information, please refer to:</p><p><a href="/operations-knowledge-base/vps/vps-monitoring-features-guide.html"><strong>VPS Monitoring Features Guide</strong></a></p><hr><h2 id="_7-usage" tabindex="-1">7. Usage <a class="header-anchor" href="#_7-usage" aria-label="Permalink to &quot;7. Usage&quot;">​</a></h2><p>The <strong>Usage</strong> page displays network traffic statistics for your VPS.</p><p>You can:</p><ul><li>View historical traffic usage.</li><li>Select a custom date range.</li><li>Review traffic statistics for a specific period.</li></ul><p>This information can help analyze bandwidth consumption and network usage trends.</p><hr><h2 id="_8-elastic-ip" tabindex="-1">8. Elastic IP <a class="header-anchor" href="#_8-elastic-ip" aria-label="Permalink to &quot;8. Elastic IP&quot;">​</a></h2><p>The <strong>Elastic IP</strong> page allows you to manage Elastic IP addresses purchased for your VPS.</p><p>Supported operations include:</p><ul><li>Viewing Elastic IPs.</li><li>Binding an Elastic IP.</li><li>Unbinding an Elastic IP.</li></ul><p>For detailed instructions, please refer to:</p><p><a href="/operations-knowledge-base/vps/vps-elastic-ip-user-guide.html"><strong>VPS Elastic IP Guide</strong></a></p><hr><h2 id="_9-cloud-disk" tabindex="-1">9. Cloud Disk <a class="header-anchor" href="#_9-cloud-disk" aria-label="Permalink to &quot;9. Cloud Disk&quot;">​</a></h2><p>The <strong>Cloud Disk</strong> page allows you to manage purchased Cloud Disks.</p><p>Supported operations include:</p><ul><li>Viewing Cloud Disks.</li><li>Attaching a Cloud Disk.</li><li>Detaching a Cloud Disk.</li></ul><p><strong>Note:</strong></p><p>After attaching a Cloud Disk through the control panel, you must log in to the operating system to initialize, partition (if required), format (for first use), and mount the disk before it can be used.</p><p>For detailed instructions, please refer to:</p><p><a href="/operations-knowledge-base/vps/vps-cloud-disk-user-guide.html"><strong>VPS Cloud Disk Guide</strong></a></p><hr><h2 id="_10-security-groups" tabindex="-1">10. Security Groups <a class="header-anchor" href="#_10-security-groups" aria-label="Permalink to &quot;10. Security Groups&quot;">​</a></h2><p>The <strong>Security Groups</strong> page allows you to manage network access policies for your VPS.</p><p>Supported operations include:</p><ul><li>Creating Security Groups.</li><li>Managing Security Group rules.</li><li>Attaching Security Groups.</li><li>Detaching Security Groups.</li></ul><p>Security Groups help control network access by allowing or denying specific ports and traffic.</p><p>For detailed instructions, please refer to:</p><p><a href="/operations-knowledge-base/vps/vps-security-group-user-guide.html"><strong>VPS Security Group Guide</strong></a></p><hr><h2 id="_11-snapshots" tabindex="-1">11. Snapshots <a class="header-anchor" href="#_11-snapshots" aria-label="Permalink to &quot;11. Snapshots&quot;">​</a></h2><p>The <strong>Snapshots</strong> page allows you to save the current state of your VPS for future recovery.</p><p>It is recommended to create a snapshot before:</p><ul><li>Performing system upgrades.</li><li>Installing software.</li><li>Modifying important configurations.</li><li>Deploying production services.</li></ul><p><strong>Note:</strong></p><p>Snapshots are intended for quick system recovery and should not replace regular data backups.</p><p>For detailed instructions, please refer to:</p><p><strong>VPS Snapshot Guide</strong></p><hr><h2 id="_12-frequently-asked-questions" tabindex="-1">12. Frequently Asked Questions <a class="header-anchor" href="#_12-frequently-asked-questions" aria-label="Permalink to &quot;12. Frequently Asked Questions&quot;">​</a></h2><h3 id="q1-why-doesn-t-the-vps-shut-down-immediately-after-clicking-shut-down" tabindex="-1">Q1: Why doesn&#39;t the VPS shut down immediately after clicking <strong>Shut Down</strong>? <a class="header-anchor" href="#q1-why-doesn-t-the-vps-shut-down-immediately-after-clicking-shut-down" aria-label="Permalink to &quot;Q1: Why doesn&#39;t the VPS shut down immediately after clicking **Shut Down**?&quot;">​</a></h3><p>The system performs a graceful shutdown. The time required depends on the operating system and the services currently running. Please wait a few moments and refresh the server status.</p><hr><h3 id="q2-when-should-i-use-force-shut-down-or-force-reboot" tabindex="-1">Q2: When should I use <strong>Force Shut Down</strong> or <strong>Force Reboot</strong>? <a class="header-anchor" href="#q2-when-should-i-use-force-shut-down-or-force-reboot" aria-label="Permalink to &quot;Q2: When should I use **Force Shut Down** or **Force Reboot**?&quot;">​</a></h3><p>These options should only be used when the VPS is unresponsive and cannot be shut down or restarted normally.</p><p>Whenever possible, use the standard <strong>Shut Down</strong> or <strong>Reboot</strong> options.</p><hr><h3 id="q3-will-reinstalling-the-operating-system-delete-my-data" tabindex="-1">Q3: Will reinstalling the operating system delete my data? <a class="header-anchor" href="#q3-will-reinstalling-the-operating-system-delete-my-data" aria-label="Permalink to &quot;Q3: Will reinstalling the operating system delete my data?&quot;">​</a></h3><p>Yes.</p><p>Reinstalling the operating system erases all data stored on the system disk. Please back up important data before proceeding.</p><hr><h3 id="q4-what-is-the-difference-between-vnc-and-ssh-or-windows-rdp" tabindex="-1">Q4: What is the difference between VNC and SSH (or Windows RDP)? <a class="header-anchor" href="#q4-what-is-the-difference-between-vnc-and-ssh-or-windows-rdp" aria-label="Permalink to &quot;Q4: What is the difference between VNC and SSH (or Windows RDP)?&quot;">​</a></h3><p>SSH and RDP are network-based remote access methods, while VNC provides direct console access to the server.</p><p>Even if the network is unavailable or SSH/RDP cannot connect, you can usually still manage the server through the VNC console.</p><hr><h3 id="q5-why-are-there-no-monitoring-or-usage-statistics-displayed" tabindex="-1">Q5: Why are there no monitoring or usage statistics displayed? <a class="header-anchor" href="#q5-why-are-there-no-monitoring-or-usage-statistics-displayed" aria-label="Permalink to &quot;Q5: Why are there no monitoring or usage statistics displayed?&quot;">​</a></h3><p>If the VPS has just been created, powered on, or restored, monitoring data may require some time to be collected.</p><p>Please wait a few minutes and refresh the page.</p><hr><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><p>⚠️ Before performing operations such as reinstalling the operating system or upgrading resources, it is recommended to back up important data.</p><p>⚠️ Force Shut Down and Force Reboot should only be used when normal shutdown or reboot operations are not possible.</p><p>⚠️ After attaching a Cloud Disk, you must complete the disk initialization and mounting process within the operating system before it can be used.</p><p>⚠️ Snapshots are intended for quick recovery and should not be considered a replacement for regular backups. Regular backups of important business data are strongly recommended.</p>',157)])])}const g=o(s,[["render",i]]);export{c as __pageData,g as default};
